// -----------------------------------------------------------------------------
//  🩹 Friendly AI-generation error classifier.
//  Turns raw Gemini/pipeline errors into a stable {code, message, transient}
//  so the UI can show a calm, honest message (and we know whether a retry is
//  worthwhile). Transient provider hiccups (429/503/timeout) are NOT the
//  teacher's fault and credits are always refunded for them.
// -----------------------------------------------------------------------------
function classifyGenError(err) {
  const raw = String(err?.message || err || 'Generation failed')
  const m = raw.toLowerCase()
  if (/no_lesson_content|lesson content not yet/.test(m)) {
    return { code: 'ERR_NO_SYLLABUS', transient: false, message: 'Lesson content for the selected chapter(s) has not been added yet. Please pick another chapter or contact admin.' }
  }
  if (/429|rate.?limit|resource_exhausted|quota/.test(m)) {
    return { code: 'ERR_GEMINI_BUSY', transient: true, message: 'The AI service is busy right now — no credits were charged. Please try again in a moment.' }
  }
  if (/timeout|timed out|etimedout|deadline/.test(m)) {
    return { code: 'ERR_GEMINI_TIMEOUT', transient: true, message: 'Generation is taking longer than usual — no credits were charged. Please try again.' }
  }
  if (/50[0234]|econnreset|socket hang up|network|fetch failed|unavailable/.test(m)) {
    return { code: 'ERR_GEMINI_UNAVAILABLE', transient: true, message: 'The AI service was temporarily unavailable — no credits were charged. Please try again shortly.' }
  }
  if (/gemini not configured|api key|auth/.test(m)) {
    return { code: 'ERR_GEMINI_AUTH', transient: false, message: 'AI is not configured correctly. Please contact support.' }
  }
  if (/validation|could not produce a complete/.test(m)) {
    return { code: 'ERR_VALIDATION', transient: true, message: 'The AI could not finish a complete paper this time — no credits were charged. Please tap Retry.' }
  }
  return { code: 'ERR_UNKNOWN', transient: true, message: 'Generation did not complete — no credits were charged. Please try again.' }
}

// -----------------------------------------------------------------------------
//  LO-code reconciliation helpers — ONE canonical resolver shared by the
//  Preview and Apply endpoints so both judge codes identically. Enforces
//  subject + class isolation (an EVS lesson can never keep an English code).
// -----------------------------------------------------------------------------
function loCanonClass(x) {
  if (x == null) return ''
  let s = String(x).trim().replace(/^class\s*/i, '').trim()
  if (/^\d+$/.test(s)) return String(parseInt(s, 10))
  const roman = { i: '1', ii: '2', iii: '3', iv: '4', v: '5', vi: '6', vii: '7', viii: '8', ix: '9', x: '10' }
  const low = s.toLowerCase()
  if (roman[low]) return roman[low]
  if (/shishu|balv|^bv|nursery|foundation/i.test(low)) return 'BV3'
  const m = low.match(/(\d+)/); if (m) return String(parseInt(m[1], 10))
  return s.toUpperCase()
}
function loCanonSubject(x) {
  const s = String(x || '').toLowerCase().trim()
  if (!s) return ''
  if (s.startsWith('odia') || s.includes('ଓଡ')) return 'ODIA'
  if (s.startsWith('english')) return 'ENGLISH'
  if (s.startsWith('hindi')) return 'HINDI'
  if (s.startsWith('sanskrit')) return 'SANSKRIT'
  if (s.startsWith('math') || s.includes('ଗଣିତ')) return 'MATHEMATICS'
  if (s.includes('social') || s === 'sst') return 'SOCIAL_SCIENCE'
  if ((s.startsWith('science') || s.includes('ବିଜ୍ଞାନ')) && !s.includes('social')) return 'SCIENCE'
  if (s.startsWith('evs') || s.includes('environ') || s.includes('world around') || s.includes('paribesh') || s.includes('ପରିବେଶ')) return 'EVS'
  if (['pd', 'sed', 'cd', 'lld', 'acd', 'plh', 'arts', 'art', 'general'].includes(s)) return s.toUpperCase()
  return s.toUpperCase().replace(/\s+/g, '_')
}
// Curricular-Goal / Competency / DG framework codes are NOT subject LO codes —
// they come from the curriculum framework and must be left untouched.
function loIsFrameworkCode(c) {
  const s = String(c || '').trim()
  return /^cg[-\s]?\d+/i.test(s) || /^c[-\s]?\d+\.\d+/i.test(s) || /^dg\b/i.test(s) || /^lld[-\s]/i.test(s)
}
function loNormCode(c) { return String(c || '').trim().toUpperCase().replace(/\s+/g, ' ') }


