  'revision-worksheet':      ['engagement', 'revision'],       // 5 credits
  'oral-questions':          ['engagement', 'more_questions'], // 5 credits
  'picture-based-questions': ['engagement', 'more_examples'],  // 4 credits
  'hots-questions':          ['engagement', 'hots'],           // 6 credits
