// Map Assessment Builder assessmentType → seeded (zone,type) cost row.
// FA/SA use their dedicated cost rows; open-ended (practice/unit/revision)
// fall through to the generic assessment_paper row.
function _assessmentBuilderCostKey(assessmentType) {
  const t = String(assessmentType || '').toLowerCase()
  if (/^fa\d?$/.test(t)) return ['assessment', 'fa_assessment']
  if (/^sa\d?$/.test(t)) return ['assessment', 'sa_assessment']
  return ['assessment', 'assessment_paper']
}
// Return { ok:false, response } on insufficient credits (HTTP 402),
// or { ok:true, debit, refund(reason) } on successful reservation.
async function _gateAICredit({ userId, zone, type }) {
  const cost = await aiCredit.getGenerationCost(zone, type)
  if (!cost) {
    // No configured cost → allow (safe default so a mis-mapped type doesn't 500 the user)
    return { ok: true, debit: null, refund: async () => {} }
  }
  const balance = await aiCredit.getBalance(userId)
  if (balance < cost) {
    return {
      ok: false,
      response: NextResponse.json({
        success: false,
        error: `You need ${cost} AI Credits for this generation. Your balance is ${balance}.`,
        code: 'INSUFFICIENT_AI_CREDITS',
        availableCredits: balance,
        requiredCredits: cost,
        zone, type,
      }, { status: 402 }),
    }
  }
  try {
    const debit = await aiCredit.debitCredits({ userId, cost, zone, type, cacheHit: false, meta: { source: 'round-b' } })
    return {
      ok: true,
      debit,
      refund: async (reason = 'generation_failed') => {
        try { await aiCredit.refundCredits({ userId, credits: cost, reason, relatedTxnId: debit.txnId, meta: { zone, type, source: 'round-b-refund' } }) }
        catch (e) { console.warn('[ai-credit-gate] refund failed:', e.message) }
      },
    }
  } catch (err) {
    if (err.code === 'INSUFFICIENT_CREDITS') {
      return {
        ok: false,
        response: NextResponse.json({
          success: false, error: err.message,
          code: 'INSUFFICIENT_AI_CREDITS',
          availableCredits: err.balance, requiredCredits: err.required,
          zone, type,
        }, { status: 402 }),
      }
    }
    throw err
  }
}

// ----- Razorpay singleton (server-side only) -----
const RZP_KEY_ID = process.env.NEXT_PUBLIC_RAZORPAY_KEY_ID || ''
const RZP_KEY_SECRET = process.env.RAZORPAY_KEY_SECRET || ''
let razorpayClient = null
function getRazorpay() {
  if (razorpayClient) return razorpayClient
  if (!RZP_KEY_ID || !RZP_KEY_SECRET) return null
  razorpayClient = new Razorpay({ key_id: RZP_KEY_ID, key_secret: RZP_KEY_SECRET })
  return razorpayClient
}

// Get plans from settings collection (admin-editable) or fallback to defaults.
// The Ambassador Renewal plan is appended (if not already present) so that
// /razorpay/verify and activateSubscription can resolve it. The /plans listing
// endpoint hides it from users who are not Ambassador-eligible.
// 🔒 TEMP fail-closed kill switch for the ₹99 Ambassador plan. While true, the
// plan is NEVER exposed on ANY path (plans list / Razorpay order / QR / verify)
// regardless of the Continuous-ladder switch or eligibility. Flip to false only
// when the full Ambassador rules (STEP 2) ship and are approved.
// DB-backed kill switch (admin-toggleable, DEFAULT ON). Lives in settings key
// 'ambassador_plan_kill' → { value: boolean }. When ON, the ₹99 Ambassador plan
// is NEVER exposed on ANY path (plans list / Razorpay order / QR / verify),
// regardless of the Continuous-ladder switch or eligibility. Admin turns it OFF
// (from the Referrals panel) only when the full Ambassador rules are approved.
// No .env / Secrets needed.
async function getAmbassadorKill(d) {
  try {
    const row = await d.collection('settings').findOne({ key: 'ambassador_plan_kill' })
    // Default ON (true) when unset or malformed — fail safe.
    return row ? row.value !== false : true
  } catch (_) { return true }
}
async function getActivePlans(d) {
  const doc = await d.collection('settings').findOne({ key: 'plans' })
  const base = (doc?.value && Array.isArray(doc.value)) ? [...doc.value] : [...DEFAULT_PLANS]
  try {
    const { getAmbassadorConfig, buildAmbassadorPlan, AMBASSADOR_PLAN_ID } = await import('@/lib/ambassador-plan.js')
    if (await getAmbassadorKill(d)) {
      // Strip the ₹99 plan everywhere — nothing can list, quote, order or verify it.
      return base.filter(p => p.id !== AMBASSADOR_PLAN_ID)
    }
    // Normalize ANY db-defined ambassador entry so gating (ambassadorOnly) always
    // applies — an admin-customized plans doc may store it without the flag, which
    // previously let it be treated as a normal ₹99 plan and bypass the gate.
    let normalized = base.map(p => (p.id === AMBASSADOR_PLAN_ID ? { ...p, ambassadorOnly: true } : p))
    if (!normalized.some(p => p.id === AMBASSADOR_PLAN_ID)) {
      const cfg = await getAmbassadorConfig(d)
      normalized.push(buildAmbassadorPlan(cfg))
    }
    return normalized
  } catch (_) {}
  return base
}

const AMBASSADOR_PLAN_ID_CONST = 'ambassador-yearly'
// 🏅 Ambassador gate — returns null when OK, else { status, error }.
// A ₹99 Ambassador plan may be purchased/activated ONLY when the Continuous
// ladder is OFF *and* the teacher is Ambassador-eligible. Used by every ₹99
// money path (Razorpay create-order already inlines this; QR + verify use it).
// Gates by plan ID *or* the ambassadorOnly flag so a mis-flagged DB entry is still caught.
async function ambassadorGateBlock(d, plan, userId) {
  const isAmb = !!plan && (plan.ambassadorOnly === true || plan.id === AMBASSADOR_PLAN_ID_CONST)
  if (!isAmb) return null
  // Hard kill switch wins — block for everyone, no exceptions.
  if (await getAmbassadorKill(d)) return { status: 403, error: 'The Ambassador plan is not available right now.' }
  try {
    const { isContinuousLadderOn } = await import('@/lib/referral-engine.js')
    if (await isContinuousLadderOn(d)) {
      return { status: 403, error: 'The Ambassador plan is not active yet.' }
    }
    const { isAmbassadorEligible } = await import('@/lib/ambassador-plan.js')
    const u = await d.collection('users').findOne({ id: userId })
    if (!(await isAmbassadorEligible(d, u))) {
      return { status: 403, error: 'ଏହି ପ୍ଲାନ୍ କେବଳ Ambassador milestone ପୂରଣ କରିଥିବା ଶିକ୍ଷକମାନଙ୍କ ପାଇଁ। (Only for Ambassador-eligible teachers.)' }
    }
    return null
  } catch (e) {
    // Fail CLOSED: if the gate cannot be evaluated, block the ₹99 purchase.
    console.error('[ambassadorGateBlock] failed, blocking:', e?.message)
    return { status: 403, error: 'The Ambassador plan is not available right now.' }
  }
}
