// Collision-safe public reference e.g. QR-20260828-A1B2C3
function genQrRef() {
  const d = new Date()
  const ymd = `${d.getFullYear()}${String(d.getMonth() + 1).padStart(2, '0')}${String(d.getDate()).padStart(2, '0')}`
  const rand = Array.from({ length: 6 }, () => 'ABCDEFGHJKMNPQRSTUVWXYZ23456789'[Math.floor(Math.random() * 30)]).join('')
  return `QR-${ymd}-${rand}`
}
// Normalise + validate a UTR / UPI transaction id.
function normalizeUtr(v) { return String(v ?? '').trim().replace(/\s+/g, '').toUpperCase() }
function isValidUtr(v) { return /^[A-Z0-9]{6,30}$/.test(normalizeUtr(v)) }

async function getWebhookSecret(d) {
  const doc = await d.collection('settings').findOne({ key: 'razorpay_webhook_secret' })
  return doc?.value || process.env.RAZORPAY_WEBHOOK_SECRET || ''
}

const CORS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET,POST,PUT,DELETE,OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type,Authorization',
}
function json(data, init = {}) {
  if (R2Rewrite.readFlipEnabled()) {
    try {
      const s = JSON.stringify(data)
      const { body, changed } = R2Rewrite.rewriteString(s)
      if (changed) return new NextResponse(body, { ...init, headers: { 'content-type': 'application/json', ...CORS, ...(init.headers || {}) } })
    } catch (_) {}
  }
  return NextResponse.json(data, { ...init, headers: { ...(init.headers || {}), ...CORS } })
}
export async function OPTIONS() { return new NextResponse(null, { headers: CORS }) }

/**
 * Renders a WhatsApp campaign message with per-user variables.
 *   {name}    → user's display name (fallback: "Teacher")
 *   {payLink} → deep-link that opens the login page with the ₹199 Special Offer highlighted
 *   {mobile}  → user's registered mobile
 */
function renderCampaignMessage(tpl, user, payLink) {
  const name = user?.name || 'Teacher'
  return String(tpl || '')
    .replaceAll('{name}', name)
    .replaceAll('{payLink}', payLink || '')
    .replaceAll('{mobile}', user?.mobile || '')
}

// Module-level flag — prevents re-running seed on every request (cold-start optimization
// for production Atlas cluster; each new pod runs seed exactly once on first request).
let _seedRan = false
let _seedInFlight = null

async function db() {
  const d = await getDb()
  if (!_seedRan) {
    // De-duplicate concurrent first requests so we don't kick off seed N times
    if (!_seedInFlight) {
      _seedInFlight = (async () => {
        try { await seedDatabase(d); _seedRan = true }
        catch (e) { console.error('[seed] failed:', e?.message); throw e }
        finally { _seedInFlight = null }
      })()
    }
    await _seedInFlight
  }
  return d
}

