  ALL_CLASSES:        { packs: ['SHISHU_VATIKA3_FULL', 'CLASS_I_FULL', 'CLASS_II_FULL', 'CLASS_III_FULL', 'CLASS_IV_FULL', 'CLASS_V_FULL', 'CLASS_VI_FULL', 'CLASS_VII_FULL', 'CLASS_VIII_FULL', 'STAGE_TOOLKITS_FULL'], docs: [] },
