// Direct DOCUMENT children (ids) of the given bundle/school pack codes (additive to pack-based docs).
async function assessBundleDocIds(d, ownedPackCodes) {
  if (!ownedPackCodes || !ownedPackCodes.length) return []
  const maps = await d.collection('assess_bundle_children').find({ bundle_code: { $in: ownedPackCodes } }).toArray()
  return [...new Set(maps.flatMap(m => m.child_document_ids || []))]
}
// Live document count a pack_code resolves to (bundle/school → child packs + document children).
async function assessPackDocCount(d, packCode) {
  const p = await d.collection('assess_packs').findOne({ pack_code: packCode }, { projection: { _id: 0, id: 1, pack_type: 1 } })
  if (!p) return 0
  const ids = new Set([p.id])
  const docIds = new Set()
  if (p.pack_type === 'bundle' || p.pack_type === 'school') {
    const m = await d.collection('assess_bundle_children').findOne({ bundle_code: packCode })
    const cc = m?.child_pack_codes || []
    if (cc.length) (await d.collection('assess_packs').find({ pack_code: { $in: cc } }).project({ id: 1 }).toArray()).forEach(x => ids.add(x.id))
    for (const id of (m?.child_document_ids || [])) docIds.add(id)
  }
  const docLinks = await d.collection('assess_pack_items').find({ pack_id: { $in: [...ids] } }).project({ _id: 0, document_id: 1 }).toArray()
  for (const l of docLinks) docIds.add(l.document_id)
  return docIds.size
}
// Instant admin WhatsApp alert when a PAID order resolves to 0 documents (non-fatal).
async function assessAlertZeroDocs(d, order) {
  try {
    if (!order || !order.pack_code) return
    const n = await assessPackDocCount(d, order.pack_code)
    if (n > 0) return
    // De-dupe: one alert per order.
    const already = await d.collection('assess_admin_audit').findOne({ type: 'zero_doc_alert', order_id: order.id })
    if (already) return
    const toRow = await d.collection('assess_settings').findOne({ key: 'alert_whatsapp' })
    const to = (toRow && toRow.value) || '918093414633'
    const body = `⚠️ Lesson Guru — Assessment Store ALERT\n\nA PAID order resolved to 0 documents.\nPack: ${order.pack_code}\nBuyer: ${order.user_name || ''} ${order.user_mobile || ''}\nOrder: ${order.id}\n\nFix: Admin → Assessment Store → Overview → "🔗 Seed bundle links".`
    await sendWhatsApp({ to, body })
    await d.collection('assess_admin_audit').insertOne({ id: uuidv4(), type: 'zero_doc_alert', order_id: order.id, pack_code: order.pack_code, user_mobile: order.user_mobile || '', at: new Date() })
  } catch (_) { /* never block checkout */ }
}


// Build a personalised, watermarked pack ZIP on the server's temp disk and
// stream it later via a one-time token. Never stored in Cloudinary (10MB cap).
async function runAssessPackZip(jobId) {
  const d = await db()
  const jobs = d.collection('assess_pack_jobs')
  const job = await jobs.findOne({ id: jobId })
  if (!job) return
  const setJob = (p) => jobs.updateOne({ id: jobId }, { $set: { ...p, updated_at: new Date() } })
  try {
    await setJob({ status: 'building' })
    const cld = await import('@/lib/cloudinary.js')
    const stampMod = await import('@/lib/assess-pdf-stamp.js')
    // Dynamic import so Next.js file-tracing ships archiver (+ deps) into the
    // standalone build; serverComponentsExternalPackages keeps webpack from
    // bundling it (its exports map otherwise breaks the production build).
    const archiver = (await import('archiver')).default
    const fs = await import('fs')
    const me = job.user
    // Expand owned pack (+bundle/school children) → docs.
    const pack = await d.collection('assess_packs').findOne({ pack_code: job.pack_code })
    const codes = [job.pack_code]
    if (pack && (pack.pack_type === 'bundle' || pack.pack_type === 'school')) {
      const m = await d.collection('assess_bundle_children').findOne({ bundle_code: job.pack_code })
      if (m) codes.push(...(m.child_pack_codes || []))
    }
    const packs = await d.collection('assess_packs').find({ pack_code: { $in: codes } }).project({ id: 1 }).toArray()
    const links = await d.collection('assess_pack_items').find({ pack_id: { $in: packs.map(p => p.id) } }).project({ document_id: 1 }).toArray()
    const docIds = [...new Set(links.map(l => l.document_id))]
    for (const bid of await assessBundleDocIds(d, codes)) if (!docIds.includes(bid)) docIds.push(bid)
    const docs = await d.collection('assess_documents').find({ id: { $in: docIds } }).toArray()
    // Access settings.
    const setting = async (k, dflt) => { const r = await d.collection('assess_settings').findOne({ key: k }); return r ? r.value : dflt }
    const verifyTypes = await setting('verify_doc_types', ['FA-1', 'FA-2', 'SA-1', 'Answer Key'])
    const verifyAll = (await setting('require_verification_all', false)) === true
    const legacy = (await setting('require_teacher_verification', true)) !== false
    const prof = await d.collection('assess_teacher_profiles').findOne({ user_id: me.id })
    const verified = !!prof && (prof.status === 'approved' || prof.status === 'verified')
    const userRec = await d.collection('users').findOne({ id: me.id }).catch(() => null)
    const isAdmin = userRec?.role === 'admin'
    const identity = stampMod.buildLicenseIdentity(me, prof || {}, { adminTest: isAdmin })
    const orderRec = await d.collection('assess_orders').findOne({ user_id: me.id, pack_code: job.pack_code, status: 'paid' })
    const orderId = orderRec?.id || ''
    const now = new Date()
    // Prepare temp ZIP on disk (NEVER stored in Cloudinary) + archiver stream.
    const dir = '/tmp/assess_packs'
    try { fs.mkdirSync(dir, { recursive: true }) } catch (_) {}
    const fp = `${dir}/${jobId}.zip`
    const output = fs.createWriteStream(fp)
    const archive = archiver('zip', { zlib: { level: 6 } })
    const closed = new Promise((resolve, reject) => { output.on('close', resolve); output.on('error', reject); archive.on('error', reject) })
    archive.pipe(output)
    const included = [], skipped = []
    await setJob({ total: docs.length, done: 0 })
    let done = 0
    for (const doc of docs) {
      const needsV = !doc.is_free_sample && legacy && (verifyAll || (Array.isArray(verifyTypes) && verifyTypes.includes(doc.doc_type)))
      const released = !doc.release_at || new Date(doc.release_at) <= now
      const fileOk = !!doc.cld_public_id
      if (needsV && !verified) { skipped.push(`${doc.title_or} — ଯାଞ୍ଚ ଅପେକ୍ଷାରେ`); done++; await setJob({ done }); continue }
      if (!released) { skipped.push(`${doc.title_or} — ଉପଲବ୍ଧ ହେବ: ${new Date(doc.release_at).toLocaleDateString('en-IN')}`); done++; await setJob({ done }); continue }
      if (!fileOk) { skipped.push(`${doc.title_or} — ଫାଇଲ୍ ପ୍ରସ୍ତୁତ ହେଉଛି`); done++; await setJob({ done }); continue }
      try {
        const copyId = uuidv4().slice(0, 8).toUpperCase()
        // Fetch the master SERVER-SIDE (no transformations), then stamp it with
        // the SAME personal-copy function used by single downloads.
        const masterUrl = cld.signedAssessDownloadUrl(doc.cld_public_id, { resourceType: doc.cld_resource_type || 'image', format: doc.cld_format || 'pdf', expiresInSeconds: 120 })
        const r = await fetch(masterUrl)
        if (!r || !r.ok) throw new Error('fetch ' + (r ? r.status : 'null'))
        const masterBuf = Buffer.from(await r.arrayBuffer())
        const info = { ...identity, orderId, copyId, dateStr: now.toISOString().slice(0, 10) }
        const stampedBuf = await stampMod.buildPersonalCopy(masterBuf, info)
        const folder = `${(doc.class || 'Misc').replace(/[\/\\]/g, ' ')}/${(doc.subject || 'General').replace(/[\/\\]/g, ' ')}`
        archive.append(stampedBuf, { name: `${folder}/${doc.file_name || (doc.id + '.pdf')}` })
        included.push(doc)
        await d.collection('assess_copies').insertOne({ id: uuidv4(), copy_id: copyId, user_id: me.id, user_name: me.name || '', user_mobile: me.mobile || '', document_id: doc.id, document_title: doc.title_or || '', order_id: orderId, admin_test: isAdmin, pack_code: job.pack_code, via: 'pack_zip', oath_acceptance_id: job.oath_acceptance_id || null, oath_typed_name: job.oath_typed_name || '', oath_accepted_at: job.oath_accepted_at || null, at: new Date() })
      } catch (e) { skipped.push(`${doc.title_or} — ତ୍ରୁଟି`) }
      done++; await setJob({ done })
    }
    const readme = [
      `ମୂଲ୍ୟାୟନ ଭଣ୍ଡାର — ${pack?.pack_name || job.pack_code}`,
      `ଅନୁମତିପ୍ରାପ୍ତ: ${me.name || ''} (${me.mobile || ''})`,
      `ଏହି ପ୍ୟାକ୍ କେବଳ ଆପଣଙ୍କ ବ୍ୟକ୍ତିଗତ ଶିକ୍ଷାଦାନ ପାଇଁ। ପ୍ରତ୍ୟେକ PDF ୱାଟରମାର୍କ ହୋଇଛି। ପୁନଃବଣ୍ଟନ ନିଷେଧ।`,
      ``, `ଅନ୍ତର୍ଭୁକ୍ତ: ${included.length}`, `ବାଦ୍ ଦିଆଯାଇଛି: ${skipped.length}`,
      ...skipped.map(s => `  - ${s}`),
    ].join('\n')
    archive.append(Buffer.from(readme, 'utf8'), { name: 'README.txt' })
    await archive.finalize()
    await closed
    const token = uuidv4()
    await setJob({ status: 'done', token, file_path: fp, token_expires: new Date(Date.now() + 5 * 60 * 1000), included: included.length, skipped: skipped.length, skipped_list: skipped, finished_at: new Date() })
  } catch (e) {
    await setJob({ status: 'error', error: e?.message || 'Pack build failed', finished_at: new Date() })
  }
}

async function runAssessZipExtraction(jobId) {
  const d = await db()
  const jobs = d.collection('assess_extract_jobs')
  const job = await jobs.findOne({ id: jobId })
  if (!job) return
  const setJob = (patch) => jobs.updateOne({ id: jobId }, { $set: { ...patch, updated_at: new Date() } })
  try {
    await setJob({ status: 'downloading' })
    const cld = await import('@/lib/cloudinary.js')
    const AdmZip = (await import('adm-zip')).default
    const fs = await import('fs')
    const url = cld.signedRawAssetUrl(job.zip_public_id, { expiresInSeconds: 1800, format: job.zip_format || 'zip' })
    const res = await fetch(url)
    if (!res.ok) throw new Error('Could not download ZIP from Cloudinary (' + res.status + ')')
    const buf = Buffer.from(await res.arrayBuffer())
    await setJob({ status: 'extracting' })
    const zip = new AdmZip(buf)
    const entries = zip.getEntries().filter(e => !e.isDirectory && /\.pdf$/i.test(e.entryName) && !e.entryName.includes('__MACOSX') && !e.entryName.split('/').pop().startsWith('.'))
    const slug = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 60)
    const cleanClass = (s) => String(s || '').replace(/^\d+[_\-\s]*/, '').replace(/_/g, ' ').replace(/\bClass\b/i, 'Class').trim()
    let uploaded = 0, skipped = 0, notInCatalog = 0, failed = 0
    const failures = []
    await setJob({ total: entries.length, uploaded: 0, skipped: 0, not_in_catalog: 0, failed: 0 })
    for (let i = 0; i < entries.length; i++) {
      const e = entries[i]
      const parts = e.entryName.split('/').filter(Boolean)
      const fileName = parts[parts.length - 1]
      // Detect class/subject from folder path: e.g. 06_Class_VI/Mathematics/x.pdf
      const folderClass = parts.length >= 3 ? cleanClass(parts[parts.length - 3]) : ''
      const folderSubject = parts.length >= 2 ? parts[parts.length - 2].replace(/_/g, ' ').trim() : ''
      try {
        const existing = await d.collection('assess_documents').findOne({ file_name: fileName })
        if (existing && existing.cld_public_id && !job.replace) { skipped++; await setJob({ skipped }); continue }
        const cls = existing?.class || folderClass || job.class || ''
        const subj = existing?.subject || folderSubject || job.subject || ''
        const folder = `lesson-guru/assessment-store/${slug(cls) || 'incoming'}/${slug(subj) || 'misc'}`
        const pid = `${folder}/${slug(fileName.replace(/\.pdf$/i, '')) || ('doc-' + i)}`.replace(folder + '/', '') // public_id relative to folder
        const up = await cld.uploadBufferAssessAsset(e.getData(), { folder, publicId: pid, tags: [cls, subj].filter(Boolean) })
        const fileFields = { cld_public_id: up.publicId, cld_resource_type: 'image', cld_version: up.version, bytes: up.bytes, cld_format: 'pdf', pages: up.pages || 0, updated_at: new Date() }
        // Mirror the new private master into PRIVATE R2 (Item 3) — best-effort.
        try {
          const { mirrorPrivateEnabled, putPrivatePdfBuffer } = await import('@/lib/assess-storage.js')
          if (mirrorPrivateEnabled()) {
            const mir = await putPrivatePdfBuffer(e.getData(), { docId: existing?.id, publicId: up.publicId })
            fileFields.r2_master_key = mir.r2_master_key
          }
        } catch (err2) { console.error('[assess-r2-mirror] zip-extract', err2?.message) }
        if (existing) {
          await d.collection('assess_documents').updateOne({ id: existing.id }, { $set: fileFields })
          uploaded++
        } else if (cls || subj) {
          // Not in catalog but we know class/subject → create a new doc.
          await d.collection('assess_documents').insertOne({
            id: uuidv4(), file_name: fileName, title_or: fileName.replace(/_/g, ' ').replace(/\.pdf$/i, ''),
            class: cls, subject: subj, doc_type: '', set_b: false, is_free_sample: false,
            release_at: null, exam_window_note: '', status: 'active', created_at: new Date(), ...fileFields,
          })
          uploaded++; notInCatalog++
        } else {
          notInCatalog++
        }
        await setJob({ uploaded, not_in_catalog: notInCatalog, done_count: i + 1 })
      } catch (err) {
        failed++; failures.push({ file: fileName, reason: err?.message || 'upload failed' })
        await setJob({ failed, failures })
      }
    }
    // Delete the ZIP from Cloudinary unless admin chose to keep it.
    if (job.delete_zip !== false) { try { await cld.deleteRawAssessAsset(job.zip_public_id) } catch (_) {} }
    await setJob({ status: 'done', uploaded, skipped, not_in_catalog: notInCatalog, failed, failures, finished_at: new Date() })
  } catch (e) {
    await setJob({ status: 'error', error: e?.message || 'Extraction failed', finished_at: new Date() })
  }
}


// Strips sensitive fields from a user doc before sending it to a NON-ADMIN client
// (e.g. /auth/me, /auth/login, /auth/register responses).  Admin endpoints
// intentionally bypass this so support staff can see stored plaintext for helping users.
function stripUser(u) {
  if (!u) return null
  const { password, _id, lastKnownPassword, lastKnownPasswordAt, lastKnownPasswordBy, ...rest } = u
  return rest
}

// -----------------------------------------------------------------------------
// 🔁 reconcileUserSubscription — cheap, in-flight subscription hygiene that
// runs whenever we load a fresh user document.  Handles two edge cases the
// old flow didn't cover:
//
//   1) Auto-EXPIRE — if `subscription.status === 'active'` but
//      `expiryDate <= now`, flip status to 'expired'.  Without this, the
//      user document keeps showing as active in admin analytics + drip
//      filters exclude expired users from the upgrade nudge.
//
//   2) Auto-ACTIVATE scheduled DOWNGRADE — if the user had scheduled a
//      lower-priced plan (via /razorpay/create-order returning
//      scheduleOnly=true), we persisted `subscription.scheduledDowngrade`.
//      When the current plan expires, we now transparently move them to
//      the scheduled plan (days-from-now).
//
// Returns the (possibly updated) user document.  Never throws.
// -----------------------------------------------------------------------------
async function reconcileUserSubscription(d, user) {
  if (!user) return user
  const sub = user.subscription
  if (!sub) return user
  const now = Date.now()
  const expiryMs = sub.expiryDate ? new Date(sub.expiryDate).getTime() : 0
  const isExpiredButActive = sub.status === 'active' && expiryMs && expiryMs <= now
  if (!isExpiredButActive) return user

  const sd = sub.scheduledDowngrade
  if (sd && sd.planId && Number(sd.planDays) > 0) {
    // ✨ Activate the scheduled downgrade — start fresh from now.
    const newStart = new Date()
    const newExpiry = new Date(now + Number(sd.planDays) * 86_400_000)
    // NOTE: MongoDB rejects $set + $unset on overlapping paths (error 40
    // "ConflictingUpdateOperators").  Since we're REPLACING the whole
    // `subscription` sub-doc, scheduledDowngrade naturally disappears
    // because `nextSub` doesn't include it.  No $unset needed.
    const nextSub = {
      plan:       sd.planId,
      startDate:  newStart,
      expiryDate: newExpiry,
      status:     'active',
      activatedFromDowngrade: true,
      previousPlan: sub.plan,
    }
    try {
      await d.collection('users').updateOne(
        { id: user.id },
        { $set: { subscription: nextSub } },
      )
      await d.collection('admin_logs').insertOne({
        id: uuidv4(), type: 'downgrade_activated', severity: 'info',
        userId: user.id, fromPlan: sub.plan, toPlan: sd.planId,
        startDate: newStart, expiryDate: newExpiry, createdAt: new Date(),
      }).catch(() => {})
    } catch (err) {
      console.error('[reconcile] downgrade activation failed:', err?.message)
      return user // don't return stale state — the next request will retry
    }
    return { ...user, subscription: nextSub }
  }

  // Otherwise just mark expired.
  await d.collection('users').updateOne(
    { id: user.id },
    { $set: { 'subscription.status': 'expired', 'subscription.expiredAt': new Date() } },
  )
  return { ...user, subscription: { ...sub, status: 'expired', expiredAt: new Date() } }
}

// -----------------------------------------------------------------------------
// 🛠  reconcileStuckPaymentLocks — resets `status='activating'` payments
// that have been in flight for > 10 minutes.  Prevents "user paid but
// never got activated" scenarios when /verify crashes/times out between
// acquiring the lock and completing the write.  Called opportunistically
// from the /razorpay/verify + /razorpay/webhook paths (cheap indexed scan).
// -----------------------------------------------------------------------------
async function reconcileStuckPaymentLocks(d) {
  const cutoff = new Date(Date.now() - 10 * 60 * 1000) // 10 min
  const stuck = await d.collection('payments').find({
    status: 'activating',
    $or: [
      { activationStartedAt: { $lt: cutoff } },
      { activationStartedAt: { $exists: false } },
    ],
  }).limit(20).toArray()
  for (const p of stuck) {
    await d.collection('payments').updateOne(
      { id: p.id, status: 'activating' },
      { $set: { status: 'pending', activationError: 'stale_lock_reset', activationResetAt: new Date() } },
    )
    await d.collection('admin_logs').insertOne({
      id: uuidv4(), type: 'stale_payment_lock_reset', severity: 'warn',
      paymentId: p.id, orderId: p.razorpay_order_id, userId: p.userId,
      lockedSinceMs: p.activationStartedAt ? (Date.now() - new Date(p.activationStartedAt).getTime()) : null,
      createdAt: new Date(),
    }).catch(() => {})
  }
  return stuck.length
}

// ---------------------------------------------------------------------------
// LO Code fuzzy-subject inference has been RETIRED (2026-06 Master-Fix rules).
// Previously this file exposed `subjectFromBookText()` which used Odia/English/
// Hindi keyword regex to guess a subject from the book name — that helper
// caused cross-subject LO Code contamination (English lessons receiving
// MIL/Odia codes, Balvatika Math lessons receiving LLD codes, etc.).
// It has been REMOVED.  All LO Code resolution now flows through:
//   /admin/lo-correction/*      (Step-E deterministic manual correction)
//   loCodes collection          (official source of truth)
//   lesson.loCodes (stored)     (canonical resolver)
// No path in the API infers a subject from book/lesson title text any more.
// ---------------------------------------------------------------------------

function isActive(u) {
  if (!u?.subscription) return false
  if (u.subscription.status !== 'active') return false
  if (!u.subscription.expiryDate) return false
  return new Date(u.subscription.expiryDate) > new Date()
}

// ---------------------------------------------------------------------------
//  🌅 Ajira Pathya Jojana — access + pricing helpers
// ---------------------------------------------------------------------------
//  Business rules (per user spec):
//    • Yearly Premium subscribers   → FREE access (bundled).
//    • Monthly / Quarterly Premium  → must pay ₹99/year add-on to unlock.
//    • Non-subscribers              → must pay ₹199/year standalone.
//    • Admins                       → always allowed.
//  Purchases are stored in `ajira_addons` with a 365-day validity window.
// ---------------------------------------------------------------------------
// Pricing tiers ↓ paywall by user's current subscription plan.
//  • yearlyAddonPrice → ₹ for Yearly Premium users (used to be bundled free)
//  • addonPrice       → ₹ for Monthly / Quarterly / Half-Yearly Premium users
//  • standalonePrice  → ₹ for users with NO active subscription
//  • mrpPrice         → struck-through “full price” shown on the paywall
const AJIRA_DEFAULTS = { yearlyAddonPrice: 49, addonPrice: 149, standalonePrice: 199, mrpPrice: 1499, enabled: true }

async function loadAjiraSettings(d) {
  const s = await d.collection('settings').findOne({ key: 'ajira_pricing' })
  return { ...AJIRA_DEFAULTS, ...(s?.value || {}) }
}

async function getAjiraAccess(d, user) {
  const settings = await loadAjiraSettings(d)
  const isAdminLike = ['admin', 'section_uploader', 'books_uploader'].includes(user?.role)
  if (isAdminLike) {
    return { hasAccess: true, source: 'admin', settings, addon: null, priceRupees: null }
  }
  if (!settings.enabled) {
    return { hasAccess: false, source: 'disabled', settings, addon: null, priceRupees: null }
  }
  // Figure out which price bucket this user falls into so we can quote the
  // right upgrade offer if they don't yet have an active addon.
  const premiumActive = isActive(user)
  const planId = user?.subscription?.plan || ''
  const isYearly = /yearly|annual|year/i.test(planId) || planId === 'yearly'
  const priceForUser = premiumActive
    ? (isYearly ? settings.yearlyAddonPrice : settings.addonPrice)  // ₹49 for yearly, ₹149 for monthly/quarterly/half-yearly
    : settings.standalonePrice                                        // ₹199 for users with no active sub
  // 1) Active add-on purchase (grants access regardless of subscription tier)
  const addon = await d.collection('ajira_addons').findOne(
    { userId: user?.id, status: 'active', expiresAt: { $gt: new Date() } },
    { sort: { expiresAt: -1 } },
  )
  if (addon) {
    return { hasAccess: true, source: 'addon', settings, addon, priceRupees: priceForUser }
  }
  // 2) Locked — needs to pay.  Source string tells the UI which pricing tier
  //    to render in the paywall copy.
  return {
    hasAccess: false,
    source: premiumActive
      ? (isYearly ? 'yearly-premium' : 'premium-monthly-quarterly')
      : 'no-subscription',
    settings,
    addon: null,
    priceRupees: priceForUser,
  }
}

// ---------------------------------------------------------------------------
//  🌅 Ajira "gap-day" roll-forward (scoped fix — user request)
// ---------------------------------------------------------------------------
//  The bundled curriculum seed genuinely has NO lesson periods for the week
//  21/09/2026 – 26/09/2026 (and there is NO holiday flag in the data). Per the
//  user's decision, for these specific dates we transparently show the NEXT
//  available date's lesson plan while keeping the *displayed* date as the
//  requested date (i.e. remap dateISO / dateText / dayName so the UI never
//  reveals the source date). Genuine holidays that carry an explicit flag are
//  left untouched.  Scope is intentionally limited to this window for now.
const AJIRA_GAP_DATES = new Set([
  '2026-09-21', '2026-09-22', '2026-09-23', '2026-09-24', '2026-09-25', '2026-09-26',
  // 03/10/2026 (Saturday / ଶନିବାର) is a teaching day but the bundled seed has no
  // periods for it (dates jump 01/10 → 05/10). Per user request, roll forward to
  // the next available date's plan, displayed under 03.10.2026.
  '2026-10-03',
])
const _AJIRA_ODIA_WEEKDAYS = ['ରବିବାର', 'ସୋମବାର', 'ମଙ୍ଗଳବାର', 'ବୁଧବାର', 'ଗୁରୁବାର', 'ଶୁକ୍ରବାର', 'ଶନିବାର']
function _ajiraDateText(iso) { const [y, m, dd] = iso.split('-'); return `${dd}.${m}.${y}` }
function _ajiraOdiaDay(iso) { return _AJIRA_ODIA_WEEKDAYS[new Date(iso + 'T00:00:00Z').getUTCDay()] }
// Remap a set of lesson-plan docs so they *appear* to belong to targetISO.
function _remapAjiraDocsToDate(docs, targetISO) {
  const newDateText = _ajiraDateText(targetISO)
  const newDayName = _ajiraOdiaDay(targetISO)
  return (docs || []).map((doc) => {
    let header = doc.header || ''
    if (doc.dateText) header = header.split(doc.dateText).join(newDateText)
    if (doc.dayName) header = header.split(doc.dayName).join(newDayName)
    return { ...doc, dateISO: targetISO, dateText: newDateText, dayName: newDayName, header }
  })
}

// Best-effort client-IP extraction. Honors common proxy headers ordered by
// trustworthiness, so we get the true user IP even behind ingress + CDN.
function getClientIp(request) {
  const h = request.headers
  const xff = h.get('x-forwarded-for') || ''
  if (xff) return xff.split(',')[0].trim()
  return h.get('cf-connecting-ip')
    || h.get('x-real-ip')
    || h.get('x-client-ip')
    || ''
}

// ===========================================================================
//  ASSESSMENT STORE — ABUSE DETECTION (Prompt 4 §E)
//  Records anomalies in `assess_security_events` and auto-locks store downloads
//  (online view too) for the user, leaving the rest of the account untouched.
// ===========================================================================
const ASSESS_LOCK_MSG = 'ସୁରକ୍ଷା କାରଣରୁ ଆପଣଙ୍କ ଡାଉନଲୋଡ୍ ସାମୟିକ ଭାବେ ବନ୍ଦ ଅଛି । WhatsApp କରନ୍ତୁ: +91 80934 14633'

// Returns a lock object if the user's store downloads are locked, else null.
async function assessLockState(d, userId) {
  if (!userId) return null
  const u = await d.collection('users').findOne({ id: userId }, { projection: { assess_download_lock: 1, assess_blocked: 1 } })
  if (!u) return null
  if (u.assess_download_lock && u.assess_download_lock.locked) return u.assess_download_lock
  if (u.assess_blocked) return { locked: true, reason: 'admin_block' }
  return null
}

// Records an open security event and (optionally) locks the user's store downloads.
async function assessRecordSecurityEvent(d, userId, type, details, { ip = '', deviceId = '', lock = true } = {}) {
  try {
    await d.collection('assess_security_events').insertOne({
      id: uuidv4(), user_id: userId, type, details: details || {}, ip: ip || '', device_id: deviceId || '',
      created_at: new Date(), status: 'open',
    })
    if (lock) {
      await d.collection('users').updateOne({ id: userId }, { $set: { assess_download_lock: { locked: true, reason: type, at: new Date() } } })
    }
  } catch (_) { /* non-fatal */ }
}

// Evaluates the abuse rules after a SUCCESSFUL download/view. Thresholds are
// admin-editable (Store Settings). Normal multi-document use never trips these.
async function assessDetectAbuse(d, userId, { ip = '', deviceId = '', thresholds } = {}) {
  if (!userId || !thresholds) return null
  const now = Date.now()
  const tripped = []
  // Rule 1: > N successful downloads in 1 hour (excludes online view + reset rows)
  if (thresholds.perHour > 0) {
    const cnt = await d.collection('assess_downloads').countDocuments({ user_id: userId, mode: { $ne: 'view' }, quota_reset: { $ne: true }, at: { $gte: new Date(now - 3600 * 1000) } })
    if (cnt > thresholds.perHour) tripped.push(['rapid_downloads', { count: cnt, window: '1h', limit: thresholds.perHour }])
  }
  // Rule 2: downloads from >= N different IPs in 24 hours
  if (thresholds.ips24h > 0) {
    const ips = await d.collection('assess_downloads').distinct('ip', { user_id: userId, ip: { $nin: [null, ''] }, at: { $gte: new Date(now - 24 * 3600 * 1000) } })
    if (ips.length >= thresholds.ips24h) tripped.push(['many_ips', { ips: ips.length, window: '24h', limit: thresholds.ips24h }])
  }
  // Rule 3: more than N device ids used for the store (all-time)
  if (thresholds.maxDevices > 0) {
    const devs = await d.collection('assess_downloads').distinct('device_id', { user_id: userId, device_id: { $nin: [null, '', 'no-device'] } })
    if (devs.length > thresholds.maxDevices) tripped.push(['many_devices', { devices: devs.length, limit: thresholds.maxDevices }])
  }
  if (tripped.length === 0) return null
  for (const [type, details] of tripped) await assessRecordSecurityEvent(d, userId, type, details, { ip, deviceId, lock: true })
  return tripped.map(t => t[0])
}

// ===========================================================================
//  ASSESSMENT STORE — RATE LIMITING (Prompt 4 §E)
//  In-memory fixed-window counters. Applies ONLY to /assess/* (public store);
//  never affects the rest of the website. Limits are admin-editable.
// ===========================================================================
let _assessRateCfg = { at: 0, cfg: null }
async function getAssessRateCfg(d) {
  if (_assessRateCfg.cfg && Date.now() - _assessRateCfg.at < 30000) return _assessRateCfg.cfg
  let m = {}
  try {
    const rows = await d.collection('assess_settings').find({ key: { $in: ['rate_per_user_min', 'rate_per_ip_min', 'rate_download_per_user_min'] } }).toArray()
    m = Object.fromEntries(rows.map(r => [r.key, r.value]))
  } catch (_) {}
  const cfg = {
    user: parseInt(m.rate_per_user_min) || 30,
    ip: parseInt(m.rate_per_ip_min) || 60,
    dl: parseInt(m.rate_download_per_user_min) || 10,
  }
  _assessRateCfg = { at: Date.now(), cfg }
  return cfg
}
const _assessRateBuckets = new Map()
function assessRateAllow(key, limit) {
  if (!limit || limit <= 0) return true
  const now = Date.now(), w = 60000
  let arr = (_assessRateBuckets.get(key) || []).filter(t => t > now - w)
  const ok = arr.length < limit
  if (ok) { arr.push(now); _assessRateBuckets.set(key, arr) } else { _assessRateBuckets.set(key, arr) }
  return ok
}


