// IST wall-clock helper (server runs UTC): local + (330 - offset) minutes → IST.
function _istNow(now = new Date()) { return new Date(now.getTime() + (5.5 * 60 - now.getTimezoneOffset()) * 60000) }
// 🎯 ONE canonical server-side visibility resolver used everywhere.
//    Returns { visible, reason }. Reasons: DISABLED | PLACEMENT_NOT_ENABLED |
//    NOT_STARTED | EXPIRED | OUTSIDE_DAILY_SCHEDULE | NO_ACTIVE_CAMPAIGN.
function _adVisibility(ad, placement = null, now = new Date()) {
  if (!ad) return { visible: false, reason: 'NO_ACTIVE_CAMPAIGN' }
  if (ad.status !== 'on') return { visible: false, reason: 'DISABLED' }
  if (placement && !(ad.placements || []).includes(placement)) return { visible: false, reason: 'PLACEMENT_NOT_ENABLED' }
  const sc = ad.schedule || {}
  const ist = _istNow(now)
  const dateISO = ist.toISOString().slice(0, 10)
  if (sc.startDate && dateISO < sc.startDate) return { visible: false, reason: 'NOT_STARTED' }
  if (sc.endDate && dateISO > sc.endDate) return { visible: false, reason: 'EXPIRED' }
  const cur = String(ist.getUTCHours()).padStart(2, '0') + ':' + String(ist.getUTCMinutes()).padStart(2, '0')
  if (sc.dailyStart && sc.dailyEnd) {
    if (sc.dailyStart <= sc.dailyEnd) { if (cur < sc.dailyStart || cur > sc.dailyEnd) return { visible: false, reason: 'OUTSIDE_DAILY_SCHEDULE' } }
    else { if (cur < sc.dailyStart && cur > sc.dailyEnd) return { visible: false, reason: 'OUTSIDE_DAILY_SCHEDULE' } } // overnight
  } else if (sc.dailyStart) { if (cur < sc.dailyStart) return { visible: false, reason: 'OUTSIDE_DAILY_SCHEDULE' } }
  else if (sc.dailyEnd) { if (cur > sc.dailyEnd) return { visible: false, reason: 'OUTSIDE_DAILY_SCHEDULE' } }
  return { visible: true, reason: null }
}
// Back-compat wrapper (schedule + status only, no placement).
function _adScheduleLive(ad, now = new Date()) { return _adVisibility(ad, null, now).visible }
function _validHttpUrl(u) {
  try { const p = new URL(String(u)); return p.protocol === 'http:' || p.protocol === 'https:' } catch { return false }
}
// Whitelist-sanitise an admin-supplied campaign payload into structured fields.
function _sanitizeAdInput(b = {}) {
  const out = {}
  if (typeof b.name === 'string') out.name = b.name.slice(0, 120)
  if (b.status === 'on' || b.status === 'off') out.status = b.status
  if (typeof b.showToSubscribers === 'boolean') out.showToSubscribers = b.showToSubscribers
  if (Array.isArray(b.placements)) out.placements = b.placements.filter(p => AD_PLACEMENTS.includes(p))
  if (b.schedule && typeof b.schedule === 'object') {
    const s = b.schedule
    out.schedule = {
      startDate: /^\d{4}-\d{2}-\d{2}$/.test(s.startDate || '') ? s.startDate : '',
      endDate:   /^\d{4}-\d{2}-\d{2}$/.test(s.endDate || '')   ? s.endDate   : '',
      dailyStart: /^\d{2}:\d{2}$/.test(s.dailyStart || '') ? s.dailyStart : '',
      dailyEnd:   /^\d{2}:\d{2}$/.test(s.dailyEnd || '')   ? s.dailyEnd   : '',
      timezone: 'Asia/Kolkata',
    }
  }
  if (b.frequencyPerDay !== undefined) out.frequencyPerDay = Math.max(0, Math.min(50, parseInt(b.frequencyPerDay) || 0))
  if (typeof b.showOncePerSession === 'boolean') out.showOncePerSession = b.showOncePerSession
  if (b.content && typeof b.content === 'object') {
    const c = b.content, oc = {}
    const strFields = ['headline', 'subheadline', 'ctaText', 'headlineMobile', 'subheadlineMobile', 'featuresMobileText', 'imageUrl', 'imagePublicId']
    for (const f of strFields) if (typeof c[f] === 'string') oc[f] = c[f].slice(0, 2000)
    if (Array.isArray(c.features)) oc.features = c.features.map(x => String(x).slice(0, 200)).slice(0, 20)
    if (typeof c.destinationUrl === 'string') oc.destinationUrl = c.destinationUrl.slice(0, 1000)
    out.content = oc
  }
  return out
}


// Fire-and-forget audit log for Instant Assessment Paper interactions.
// Writes one row per print/preview event so admins can drill into which
// users are engaging with which papers. Uses a bounded ttl-safe write —
// if it fails we swallow the error (never block the user-facing request).
async function logPaperActivity(dbRef, ev) {
  try {
    if (!dbRef || !ev?.paperId || !ev?.userId) return
    await dbRef.collection('official_papers_activity').insertOne({
      id: (globalThis.crypto?.randomUUID?.() || require('crypto').randomUUID()),
      paperId: ev.paperId,
      paperTitle: ev.paperTitle || '',
      className: ev.className || '',
      bookName: ev.bookName || '',
      examType: ev.examType || '',
      setLetter: ev.setLetter || '',
      year: ev.year || '',
      userId: ev.userId,
      userName: ev.userName || '',
      userMobile: ev.userMobile || '',
      userRole: ev.userRole || 'user',
      action: ev.action || 'view', // 'print' | 'preview' | 'view'
      userAgent: (ev.userAgent || '').slice(0, 300),
      ip: (ev.ip || '').slice(0, 64),
      createdAt: new Date(),
    })
  } catch (_e) { /* silent */ }
}

