// -----------------------------------------------------------------------------
// 🔔 checkSignupThresholdAndAlert — pings admin WhatsApp when today's signup
//    count first crosses the configured threshold.  Alerts at most once per
//    day per admin using a marker doc in `settings`.
// -----------------------------------------------------------------------------
async function checkSignupThresholdAndAlert(d) {
  const cfg = await d.collection('settings').findOne({ key: 'signupAlertConfig' })
  const config = cfg?.value || { enabled: false, threshold: 20, adminMobiles: [] }
  if (!config.enabled) return
  if (!Array.isArray(config.adminMobiles) || config.adminMobiles.length === 0) return
  const threshold = Number(config.threshold) || 20
  const dayStart = new Date(); dayStart.setHours(0, 0, 0, 0)
  const dayKey = dayStart.toISOString().slice(0, 10)
  const count = await d.collection('users').countDocuments({ createdAt: { $gte: dayStart } })
  if (count < threshold) return
  const marker = await d.collection('settings').findOne({ key: 'signupAlertSentToday' })
  if (marker?.value?.date === dayKey) return
  // Claim the marker first so a concurrent request can't double-alert.
  await d.collection('settings').updateOne(
    { key: 'signupAlertSentToday' },
    { $set: { key: 'signupAlertSentToday', value: { date: dayKey, count, sentAt: new Date() } } },
    { upsert: true }
  )
  try {
    const { sendSingle } = await import('@/lib/bulkymarketing.js')
    for (const mobile of config.adminMobiles) {
      await sendSingle({
        to: mobile,
        template_id: config.templateId || 'signup_spike_alert',
        language: 'en_US',
        variables: { 1: String(count), 2: String(threshold), 3: dayKey },
      }).catch((e) => console.warn('[signup-alert] send failed for', mobile, e?.message))
    }
  } catch (e) {
    console.warn('[signup-alert] Bulkymarketing send failed:', e?.message)
  }
}

